(function() {
    'use strict';

    class InnovatorAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Dilema del Innovador';
            this.version = '1.1.0';

            this.ORG_LABELS_EN = ['Core Business Unit', 'Autonomous Unit', 'External Partnership', 'University Research'];
            this.ORG_LABELS_ES = ['Unidad de Negocio Central', 'Unidad Autónoma', 'Alianza Externa', 'Investigación Universitaria'];
            this.PARTNER_LABELS_EN = ['Acquire Startup (COP 22B)', 'Joint Venture (COP 8B)', 'License Technology (COP 5B)', 'Go Organic (No cost)'];
            this.PARTNER_LABELS_ES = ['Adquirir Startup (COP 22B)', 'Joint Venture (COP 8B)', 'Licenciar Tecnología (COP 5B)', 'Crecimiento Orgánico (Sin costo)'];
            this.RESPONSE_LABELS_EN = ['Accelerate Li-Ion Investment', 'Defend Core with Price Reduction', 'Pivot Product Portfolio', 'Explore Adjacent Markets'];
            this.RESPONSE_LABELS_ES = ['Acelerar Inversión Li-Ion', 'Defender Mercado con Reducción de Precios', 'Pivotar Portafolio de Productos', 'Explorar Mercados Adyacentes'];
            this.BOOST_LABELS_EN = ['No Extra Investment', 'Moderate Boost (+COP 5B)', 'Aggressive Boost (+COP 12B)', 'All-In Push (+COP 20B)'];
            this.BOOST_LABELS_ES = ['Sin Inversión Extra', 'Impulso Moderado (+COP 5B)', 'Impulso Agresivo (+COP 12B)', 'Apuesta Total (+COP 20B)'];
            this.AUTO_LABELS_EN = ['Compete with Own Li-Ion Product', 'Exit Automotive — Defend Industrial', 'Strategic Pivot to Energy Storage', 'Seek Merger or Acquisition'];
            this.AUTO_LABELS_ES = ['Competir con Producto Li-Ion Propio', 'Salir de Automotriz — Defender Industrial', 'Pivote Estratégico a Almacenamiento', 'Buscar Fusión o Adquisición'];
            this.RESTR_LABELS_EN = ['No Restructuring', 'Moderate Restructuring', 'Major Restructuring', 'Full Transformation'];
            this.RESTR_LABELS_ES = ['Sin Reestructuración', 'Reestructuración Moderada', 'Reestructuración Mayor', 'Transformación Completa'];
            this.POS_LABELS_EN = ['Lead-Acid Specialist', 'Hybrid Energy Portfolio', 'Full Energy Storage Transition'];
            this.POS_LABELS_ES = ['Especialista en Plomo-Ácido', 'Portafolio Híbrido de Energía', 'Transición Total a Almacenamiento'];
            this.EXIT_LABELS_EN = ['Accept Acquisition Offer', 'Reject and Compete Independently', 'Counter-Offer (Partial Sale)', 'Seek Alternative Buyer'];
            this.EXIT_LABELS_ES = ['Aceptar Oferta de Adquisición', 'Rechazar y Competir Independientemente', 'Contra-Oferta (Venta Parcial)', 'Buscar Comprador Alternativo'];

            this.ORG_MULT_DISRUPTIVE = [0.55, 1.0, 1.15, 0.75];
            this.ORG_MULT_SUSTAINING = [1.0, 0.85, 0.80, 0.90];
            this.PARTNER_CAP_LION = [25, 12, 8, 0];
            this.PARTNER_CAP_LFP = [15, 8, 5, 0];
            this.PARTNER_COST = [22, 8, 5, 0];
            this.TECH_COST = { sustaining: 0.35, lion: 0.85, lfp: 0.75, solidState: 1.6 };
            this.BOOST_AMOUNT = [0, 5, 12, 20];

            this.EVENTS = [
                { prob: 0.35, en: 'Government EV Subsidy: 30% tax credit for battery EV purchases announced. EV and Li-Ion market development accelerated.', es: 'Subsidio Gubernamental EV: Crédito fiscal del 30% para compras de vehículos eléctricos. Se acelera el desarrollo del mercado Li-Ion.', lionBonus: 5, lfpBonus: 5, timelineShift: -1 },
                { prob: 0.50, en: 'Volta Technologies raises Series C (USD 180M). Solid-state timeline accelerates significantly.', es: 'Volta Technologies cierra Serie C (USD 180M). La línea temporal del estado sólido se acelera significativamente.', ssBonus: 8, timelineShift: -1 },
                { prob: 0.40, en: 'Lead-acid price collapse: Chinese overcapacity drops global prices by 25%. Core market margins under severe pressure.', es: 'Colapso de precios del plomo-ácido: Sobrecapacidad china reduce precios globales un 25%. Márgenes del mercado central bajo presión severa.', marginHit: 0.25 },
                { prob: 0.20, en: 'Strategic acquirer (Exide Technologies) offers COP 280B for EnerStar. Board requests your recommendation.', es: 'Adquirente estratégico (Exide Technologies) ofrece COP 280B por EnerStar. La Junta solicita su recomendación.', acquisitionOffer: true }
            ];
        }

        // v1.1.0 FIX: robust language read. The framework exposes the language as .lang
        // (offline player) / .language (platform) and mirrors it on <html lang>; .currentLanguage
        // is frequently undefined and silently fell back to English (the documented
        // "frame in Spanish, content in English" bug). Try all, normalise to a 2-letter code.
        _isEs() {
            var m = window.mySimulation || {};
            var l = m.language || m.currentLanguage || m.lang ||
                (typeof document !== 'undefined' && document.documentElement && document.documentElement.lang) || 'en';
            return String(l).toLowerCase().slice(0, 2) === 'es';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 45,
                    revenue: 182,
                    leadAcidRevenue: 182,
                    newTechRevenue: 0,
                    newTechPct: 0,
                    coreMarketShare: 100,
                    autoMarketShare: 100,
                    industrialMarketShare: 100,
                    deepCycleMarketShare: 100,
                    leadAcidCap: 95,
                    lionCap: 0,
                    lfpCap: 0,
                    solidStateCap: 0,
                    orgStructure: 0,
                    partnerType: 0,
                    rdBudget: 8.4,
                    rdEfficiency: 1.0,
                    evSubsidyActive: false,
                    voltaAccelerated: false,
                    priceCollapse: false,
                    acquisitionOffered: false,
                    eventLog: '',
                    revenueHistory: [],
                    leadAcidRevHistory: [],
                    newTechRevHistory: [],
                    marketShareHistory: [],
                    lionCapHistory: [],
                    lfpCapHistory: [],
                    ssCapHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    sustainingPct: 70,
                    lionPct: 15,
                    lfpPct: 10,
                    solidStatePct: 5,
                    strategyChoice: 1,
                    secondaryChoice: 1
                };
            }
            this._updateBriefing(state);
            this._setupSliderListeners();
        }

        _setupSliderListeners() {
            var self = this;
            var ids = ['sustainingInput', 'lionInput', 'lfpInput', 'solidStateInput'];
            var valIds = ['sustainingValue', 'lionValue', 'lfpValue', 'solidStateValue'];
            ids.forEach(function(id, idx) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() {
                        var valEl = document.getElementById(valIds[idx]);
                        if (valEl) valEl.textContent = el.value + '%';
                        self._updateAllocationTotal();
                    });
                }
            });
        }

        _updateAllocationTotal() {
            var s = parseInt(document.getElementById('sustainingInput').value) || 0;
            var l = parseInt(document.getElementById('lionInput').value) || 0;
            var f = parseInt(document.getElementById('lfpInput').value) || 0;
            var ss = parseInt(document.getElementById('solidStateInput').value) || 0;
            var total = s + l + f + ss;
            var el = document.getElementById('allocationTotal');
            if (el) {
                el.textContent = total + '%';
                if (total !== 100) {
                    el.classList.add('innovator-sim-over');
                } else {
                    el.classList.remove('innovator-sim-over');
                }
            }
        }

        _updateBriefing(state) {
            var round = Math.min((state.currentPeriod || 1), 4);
            var idx = round - 1;
            var ds = state.domainState || {};
            var isEs = this._isEs();

            var briefings = this._getBriefings(ds, isEs);
            var briefEl = document.getElementById('briefingText');
            if (briefEl && briefings[idx]) briefEl.innerHTML = briefings[idx];

            var stratSelect = document.getElementById('strategySelect');
            var secSelect = document.getElementById('secondarySelect');
            var stratLabel = document.getElementById('strategyLabelEl');
            var secLabel = document.getElementById('secondaryLabelEl');

            if (stratSelect) {
                stratSelect.innerHTML = '';
                var stratOpts = this._getStrategyOptions(idx, isEs);
                var stratLbl = this._getStrategyLabel(idx, isEs);
                if (stratLabel) stratLabel.textContent = stratLbl;
                stratOpts.forEach(function(opt, i) {
                    var o = document.createElement('option');
                    o.value = i + 1;
                    o.textContent = opt;
                    stratSelect.appendChild(o);
                });
            }
            if (secSelect) {
                secSelect.innerHTML = '';
                var secOpts = this._getSecondaryOptions(idx, isEs);
                var secLbl = this._getSecondaryLabel(idx, isEs);
                if (secLabel) secLabel.textContent = secLbl;
                secOpts.forEach(function(opt, i) {
                    var o = document.createElement('option');
                    o.value = i + 1;
                    o.textContent = opt;
                    secSelect.appendChild(o);
                });
            }

            var rdLabel = document.getElementById('rdBudgetLabel');
            if (rdLabel) {
                var budget = ds.rdBudget || 8.4;
                rdLabel.textContent = (isEs ? 'Presupuesto I+D disponible: COP ' : 'Available R&D Budget: COP ') + budget.toFixed(1) + 'B';
            }

            this._updateTechBars(ds);

            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            if (eventPanel && eventText) {
                if (ds.eventLog && ds.eventLog.length > 0) {
                    eventPanel.style.display = 'block';
                    eventText.innerHTML = ds.eventLog;
                } else {
                    eventPanel.style.display = 'none';
                }
            }
        }

        _getBriefings(ds, isEs) {
            if (isEs) {
                return [
                    '<strong>Ronda 1 — Diagnóstico de Portafolio Tecnológico y Asignación de I+D (Años 1-2)</strong><br><br>Usted es CEO de EnerStar Andina S.A.S., fabricante líder de baterías de plomo-ácido en Colombia con ingresos de COP 182B. Dos fuerzas disruptivas convergen: (1) la tecnología li-ion está capturando el mercado de electrónicos de consumo y apareciendo en el segmento bajo del mercado automotriz, y (2) Volta Technologies acaba de recaudar USD 45M para desarrollar baterías de estado sólido para el segmento industrial.<br><br><strong>Mapa de Amenazas Competitivas:</strong><br>• Plomo-ácido (EnerStar): Rendimiento 100% (referencia), mejora +1.5%/año<br>• Li-ion (consumo): Rendimiento 68%, mejora +8%/año — cruce automotriz en ~4 años<br>• LFP (fosfato de hierro-litio): Rendimiento 82%, mejora +9%/año — cruce industrial en ~2 años<br>• Estado sólido (Volta): Rendimiento 45%, mejora +15%/año — cruce en ~6 años<br><br>Sus clientes actuales están satisfechos. EnerStar es rentable. La pregunta es: ¿cómo se verá EnerStar en 8 años?',

                    '<strong>Ronda 2 — Señal del Mercado y Respuesta Competitiva (Años 3-5)</strong><br><br>Han pasado 2.5 años. Las baterías LFP ahora son competitivas para respaldo de telecomunicaciones — el segundo segmento más grande de EnerStar (28% de ingresos). La disrupción está ocurriendo antes de lo proyectado.<br><br>Capacidades actuales: Lead-Acid=' + Math.round(ds.leadAcidCap || 95) + ', Li-Ion=' + Math.round(ds.lionCap || 0) + ', LFP=' + Math.round(ds.lfpCap || 0) + ', Solid-State=' + Math.round(ds.solidStateCap || 0) + '<br><br>¿Cómo responde a la entrada de Li-Ion en su mercado industrial?',

                    '<strong>Ronda 3 — Punto de Crisis de Disrupción (Años 5-7)</strong><br><br>Li-ion ha cruzado al mercado automotriz. Renault Colombia y Mazda Colombia han iniciado pruebas de calificación de proveedores para alternativas li-ion. El mercado central de EnerStar (58% de ingresos) está en riesgo.<br><br>Capacidades: Lead-Acid=' + Math.round(ds.leadAcidCap || 95) + ', Li-Ion=' + Math.round(ds.lionCap || 0) + ', LFP=' + Math.round(ds.lfpCap || 0) + ', Solid-State=' + Math.round(ds.solidStateCap || 0) + '<br>Participación de mercado automotriz: ' + Math.round(ds.autoMarketShare || 100) + '% | Industrial: ' + Math.round(ds.industrialMarketShare || 100) + '%<br><br>La organización que invirtió en li-ion en rondas anteriores ahora tiene una opción competitiva. La que no, enfrenta sustitución.',

                    '<strong>Ronda 4 — Resultado Estratégico y Posicionamiento Futuro (Años 8-10)</strong><br><br>Evaluación final. Después de una década de disrupción tecnológica, ¿dónde está EnerStar?<br><br>Ingresos: COP ' + Math.round(ds.revenue || 182) + 'B | Tecnología nueva: ' + Math.round(ds.newTechPct || 0) + '% de ingresos<br>Mercado automotriz: ' + Math.round(ds.autoMarketShare || 100) + '% | Industrial: ' + Math.round(ds.industrialMarketShare || 100) + '%<br><br>Defina el posicionamiento estratégico de EnerStar para la próxima década.'
                ];
            }
            return [
                '<strong>Round 1 — Technology Portfolio Diagnosis and R&D Allocation (Years 1-2)</strong><br><br>You are CEO of EnerStar Andina S.A.S., a leading Colombian lead-acid battery manufacturer with COP 182B revenue. Two disruptive forces converge: (1) Li-ion technology is capturing consumer electronics and entering the lower end of the automotive market, and (2) Volta Technologies just raised USD 45M to develop solid-state batteries for the industrial segment.<br><br><strong>Competitive Threat Map:</strong><br>• Lead-acid (EnerStar): 100% performance (baseline), improving +1.5%/year<br>• Li-ion (consumer): 68% performance, improving +8%/year — automotive crossover in ~4 years<br>• LFP (lithium iron phosphate): 82% performance, improving +9%/year — industrial crossover in ~2 years<br>• Solid-state (Volta): 45% performance, improving +15%/year — crossover in ~6 years<br><br>Your current customers are satisfied. EnerStar is profitable. The question is: what does EnerStar look like in 8 years?',

                '<strong>Round 2 — Market Signal and Competitive Response (Years 3-5)</strong><br><br>Two and a half years have passed. LFP batteries are now competitive for telecom backup power — EnerStar second-largest segment (28% of revenue). Disruption is happening sooner than projected.<br><br>Current capabilities: Lead-Acid=' + Math.round(ds.leadAcidCap || 95) + ', Li-Ion=' + Math.round(ds.lionCap || 0) + ', LFP=' + Math.round(ds.lfpCap || 0) + ', Solid-State=' + Math.round(ds.solidStateCap || 0) + '<br><br>How do you respond to Li-Ion entering your industrial market?',

                '<strong>Round 3 — Disruption Crisis Point (Years 5-7)</strong><br><br>Li-ion has crossed into the automotive market. Renault Colombia and Mazda Colombia have begun supplier qualification trials for Li-Ion alternatives. EnerStar core market (58% of revenue) is at risk.<br><br>Capabilities: Lead-Acid=' + Math.round(ds.leadAcidCap || 95) + ', Li-Ion=' + Math.round(ds.lionCap || 0) + ', LFP=' + Math.round(ds.lfpCap || 0) + ', Solid-State=' + Math.round(ds.solidStateCap || 0) + '<br>Automotive market share: ' + Math.round(ds.autoMarketShare || 100) + '% | Industrial: ' + Math.round(ds.industrialMarketShare || 100) + '%<br><br>The organization that invested in Li-Ion in earlier rounds now has a competitive option. The one that did not is facing substitution.',

                '<strong>Round 4 — Strategic Outcome and Future Positioning (Years 8-10)</strong><br><br>Final assessment. After a decade of technological disruption, where does EnerStar stand?<br><br>Revenue: COP ' + Math.round(ds.revenue || 182) + 'B | New technology: ' + Math.round(ds.newTechPct || 0) + '% of revenue<br>Automotive share: ' + Math.round(ds.autoMarketShare || 100) + '% | Industrial: ' + Math.round(ds.industrialMarketShare || 100) + '%<br><br>Define EnerStar strategic positioning for the next decade.'
            ];
        }

        _getStrategyOptions(roundIdx, isEs) {
            if (roundIdx === 0) return isEs ? this.ORG_LABELS_ES : this.ORG_LABELS_EN;
            if (roundIdx === 1) return isEs ? this.RESPONSE_LABELS_ES : this.RESPONSE_LABELS_EN;
            if (roundIdx === 2) return isEs ? this.AUTO_LABELS_ES : this.AUTO_LABELS_EN;
            return isEs ? this.POS_LABELS_ES : this.POS_LABELS_EN;
        }

        _getSecondaryOptions(roundIdx, isEs) {
            if (roundIdx === 0) return isEs ? this.PARTNER_LABELS_ES : this.PARTNER_LABELS_EN;
            if (roundIdx === 1) return isEs ? this.BOOST_LABELS_ES : this.BOOST_LABELS_EN;
            if (roundIdx === 2) return isEs ? this.RESTR_LABELS_ES : this.RESTR_LABELS_EN;
            return isEs ? this.EXIT_LABELS_ES : this.EXIT_LABELS_EN;
        }

        _getStrategyLabel(roundIdx, isEs) {
            var labels = isEs
                ? ['Estructura Organizacional', 'Respuesta Estratégica', 'Respuesta Automotriz', 'Posicionamiento a 10 Años']
                : ['Organizational Structure', 'Strategic Response', 'Automotive Response', '10-Year Positioning'];
            return labels[roundIdx] || labels[0];
        }

        _getSecondaryLabel(roundIdx, isEs) {
            var labels = isEs
                ? ['Tipo de Alianza', 'Inversión Adicional', 'Reestructuración', 'Decisión de Salida']
                : ['Partnership Type', 'Additional Investment', 'Restructuring', 'Exit Decision'];
            return labels[roundIdx] || labels[0];
        }

        _updateTechBars(ds) {
            var techs = [
                { bar: 'laBar', val: 'laCapDisplay', cap: ds.leadAcidCap || 95 },
                { bar: 'liBar', val: 'liCapDisplay', cap: ds.lionCap || 0 },
                { bar: 'lfpBar', val: 'lfpCapDisplay', cap: ds.lfpCap || 0 },
                { bar: 'ssBar', val: 'ssCapDisplay', cap: ds.solidStateCap || 0 }
            ];
            techs.forEach(function(t) {
                var barEl = document.getElementById(t.bar);
                var valEl = document.getElementById(t.val);
                if (barEl) barEl.style.width = Math.round(t.cap) + '%';
                if (valEl) valEl.textContent = Math.round(t.cap);
            });
        }

        validateDecisions(decisions) {
            var s = parseInt(document.getElementById('sustainingInput').value) || 0;
            var l = parseInt(document.getElementById('lionInput').value) || 0;
            var f = parseInt(document.getElementById('lfpInput').value) || 0;
            var ss = parseInt(document.getElementById('solidStateInput').value) || 0;
            var total = s + l + f + ss;

            if (total !== 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('alloc_warning'), 'warning'
                );
                return false;
            }

            decisions.sustainingPct = s;
            decisions.lionPct = l;
            decisions.lfpPct = f;
            decisions.solidStatePct = ss;

            var stratEl = document.getElementById('strategySelect');
            if (stratEl) decisions.strategyChoice = parseInt(stratEl.value);
            var secEl = document.getElementById('secondarySelect');
            if (secEl) decisions.secondaryChoice = parseInt(secEl.value);

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            var rdBudget = ds.rdBudget;
            var orgIdx = (ds.orgStructure || 1) - 1;
            if (round === 1) {
                orgIdx = d.strategyChoice - 1;
                ds.orgStructure = d.strategyChoice;
                ds.partnerType = d.secondaryChoice;
                var pIdx = d.secondaryChoice - 1;
                ds.lionCap += this.PARTNER_CAP_LION[pIdx];
                ds.lfpCap += this.PARTNER_CAP_LFP[pIdx];
                ds.cash -= this.PARTNER_COST[pIdx];
            }

            var boostAmount = 0;
            if (round === 2) {
                boostAmount = this.BOOST_AMOUNT[(d.secondaryChoice || 1) - 1];
                ds.cash -= boostAmount;
            }

            var totalRd = rdBudget + boostAmount;
            var sustInv = totalRd * (d.sustainingPct / 100);
            var lionInv = totalRd * (d.lionPct / 100);
            var lfpInv = totalRd * (d.lfpPct / 100);
            var ssInv = totalRd * (d.solidStatePct / 100);

            var orgMultD = this.ORG_MULT_DISRUPTIVE[orgIdx] || 0.55;
            var orgMultS = this.ORG_MULT_SUSTAINING[orgIdx] || 1.0;

            var sustGain = (sustInv / this.TECH_COST.sustaining) * orgMultS * 0.35;
            var lionGain = (lionInv / this.TECH_COST.lion) * orgMultD * 2.8;
            var lfpGain = (lfpInv / this.TECH_COST.lfp) * orgMultD * 2.8;
            var ssGain = (ssInv / this.TECH_COST.solidState) * orgMultD * 2.5;

            ds.leadAcidCap = Math.min(100, ds.leadAcidCap + sustGain);
            ds.lionCap = Math.min(100, ds.lionCap + lionGain);
            ds.lfpCap = Math.min(100, ds.lfpCap + lfpGain);
            ds.solidStateCap = Math.min(100, ds.solidStateCap + ssGain);

            var eventMsg = '';
            var evt = this.EVENTS[round - 1];
            if (evt && Math.random() < evt.prob) {
                eventMsg = this._isEs() ? evt.es : evt.en;
                if (evt.lionBonus) ds.lionCap = Math.min(100, ds.lionCap + evt.lionBonus);
                if (evt.lfpBonus) ds.lfpCap = Math.min(100, ds.lfpCap + evt.lfpBonus);
                if (evt.ssBonus) ds.solidStateCap = Math.min(100, ds.solidStateCap + evt.ssBonus);
                if (evt.marginHit) ds.priceCollapse = true;
                if (evt.acquisitionOffer) ds.acquisitionOffered = true;
                if (round === 1) ds.evSubsidyActive = true;
                if (round === 2) ds.voltaAccelerated = true;
            }
            ds.eventLog = eventMsg;

            var baseAutoRev = 182 * 0.58;
            var baseIndRev = 182 * 0.28;
            var baseDeepRev = 182 * 0.14;
            var growthFactor = 1 + (round * 0.025);

            if (round >= 2) {
                var indThreshold = 40;
                if (ds.evSubsidyActive) indThreshold = 35;
                var bestIndCap = Math.max(ds.lionCap, ds.lfpCap);
                if (bestIndCap < indThreshold) {
                    var indLoss = Math.min(60, (indThreshold - bestIndCap) * 1.8);
                    ds.industrialMarketShare = Math.max(40, ds.industrialMarketShare - indLoss);
                } else {
                    ds.industrialMarketShare = Math.min(100, ds.industrialMarketShare + 2);
                }
                if (d.strategyChoice === 2 && round === 2) {
                    ds.industrialMarketShare = Math.min(100, ds.industrialMarketShare + 8);
                    ds.cash -= 4;
                }
            }

            if (round >= 3) {
                var autoThreshold = 60;
                if (ds.evSubsidyActive) autoThreshold = 55;
                if (ds.lionCap < autoThreshold) {
                    var autoLoss = Math.min(55, (autoThreshold - ds.lionCap) * 1.3);
                    ds.autoMarketShare = Math.max(25, ds.autoMarketShare - autoLoss);
                } else {
                    ds.autoMarketShare = Math.min(100, ds.autoMarketShare - 5 + (ds.lionCap - autoThreshold) * 0.5);
                }
                if (round === 3) {
                    if (d.strategyChoice === 2) {
                        ds.autoMarketShare = Math.max(10, ds.autoMarketShare - 20);
                        ds.industrialMarketShare = Math.min(100, ds.industrialMarketShare + 10);
                    } else if (d.strategyChoice === 3) {
                        ds.deepCycleMarketShare = Math.min(120, ds.deepCycleMarketShare + 15);
                    } else if (d.strategyChoice === 4) {
                        ds.cash += 15;
                    }
                }
                if (round === 3 && d.secondaryChoice >= 2) {
                    var restrBonus = [0, 0.08, 0.15, 0.22];
                    var restrCost = [0, 3, 7, 14];
                    orgMultD = Math.min(1.2, orgMultD + restrBonus[d.secondaryChoice - 1]);
                    ds.cash -= restrCost[d.secondaryChoice - 1];
                }
            }

            if (round === 4) {
                if (d.strategyChoice === 1) {
                    ds.autoMarketShare = Math.max(20, ds.autoMarketShare - 10);
                    ds.leadAcidCap = Math.min(100, ds.leadAcidCap + 3);
                } else if (d.strategyChoice === 2) {
                    ds.autoMarketShare = Math.max(20, ds.autoMarketShare - 3);
                } else if (d.strategyChoice === 3) {
                    ds.autoMarketShare = Math.max(10, ds.autoMarketShare - 8);
                    ds.lionCap = Math.min(100, ds.lionCap + 5);
                    ds.lfpCap = Math.min(100, ds.lfpCap + 5);
                    ds.solidStateCap = Math.min(100, ds.solidStateCap + 3);
                }
                if (ds.acquisitionOffered && d.secondaryChoice === 1) {
                    ds.cash += 280;
                    eventMsg += (eventMsg ? '<br>' : '') + (this._isEs() ? 'Adquisición completada: COP 280B recibidos.' : 'Acquisition completed: COP 280B received.');
                    ds.eventLog = eventMsg;
                }
            }

            if (ds.priceCollapse) {
                growthFactor *= 0.82;
            }

            var laAutoRev = baseAutoRev * (ds.autoMarketShare / 100) * growthFactor;
            var laIndRev = baseIndRev * (ds.industrialMarketShare / 100) * growthFactor;
            var laDeepRev = baseDeepRev * (ds.deepCycleMarketShare / 100) * growthFactor;
            ds.leadAcidRevenue = Math.round(laAutoRev + laIndRev + laDeepRev);

            var newTechMarketBase = 30 * round;
            var lionRev = ds.lionCap > 25 ? (ds.lionCap / 100) * newTechMarketBase * 0.5 : 0;
            var lfpRev = ds.lfpCap > 25 ? (ds.lfpCap / 100) * newTechMarketBase * 0.35 : 0;
            var ssRev = ds.solidStateCap > 35 ? (ds.solidStateCap / 100) * newTechMarketBase * 0.25 : 0;
            ds.newTechRevenue = Math.round(lionRev + lfpRev + ssRev);

            ds.revenue = ds.leadAcidRevenue + ds.newTechRevenue;
            ds.newTechPct = ds.revenue > 0 ? Math.round((ds.newTechRevenue / ds.revenue) * 100) : 0;

            var totalAutoInd = ds.autoMarketShare * 0.58 + ds.industrialMarketShare * 0.28 + ds.deepCycleMarketShare * 0.14;
            ds.coreMarketShare = Math.round(totalAutoInd);

            var ebitdaMargin = 0.182;
            if (ds.priceCollapse) ebitdaMargin = 0.14;
            var ebitda = ds.revenue * ebitdaMargin;
            var rdSpend = totalRd;
            ds.cash += ebitda - rdSpend;
            ds.cash = Math.round(ds.cash * 10) / 10;

            ds.rdBudget = Math.round(ds.revenue * 0.046 * 10) / 10;
            ds.rdEfficiency = ds.rdBudget > 0 ? Math.round((ds.revenue / (ds.rdBudget * round)) * 100) / 100 : 1;

            ds.revenueHistory.push(ds.revenue);
            ds.leadAcidRevHistory.push(ds.leadAcidRevenue);
            ds.newTechRevHistory.push(ds.newTechRevenue);
            ds.marketShareHistory.push(ds.coreMarketShare);
            ds.lionCapHistory.push(Math.round(ds.lionCap));
            ds.lfpCapHistory.push(Math.round(ds.lfpCap));
            ds.ssCapHistory.push(Math.round(ds.solidStateCap));

            var results = {
                period: round,
                revenue: ds.revenue,
                leadAcidRevenue: ds.leadAcidRevenue,
                newTechRevenue: ds.newTechRevenue,
                newTechPct: ds.newTechPct,
                coreMarketShare: ds.coreMarketShare,
                autoMarketShare: Math.round(ds.autoMarketShare),
                industrialMarketShare: Math.round(ds.industrialMarketShare),
                lionCap: Math.round(ds.lionCap),
                lfpCap: Math.round(ds.lfpCap),
                solidStateCap: Math.round(ds.solidStateCap),
                cash: ds.cash,
                event: eventMsg
            };

            // v1.1.0 P0 FIX: render next round's briefing/options synchronously. Old setTimeout
            // fired AFTER the framework incremented state.currentPeriod, so (currentPeriod + 1)
            // overshot by one and showed round N+2's briefing/strategy options for rounds 2+.
            // Pre-increment here, currentPeriod is still N so (N + 1) is the correct next round.
            this._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });

            return results;
        }

