        getPerformanceSummary(history) {
            if (!history.length) return {};
            var isEs = this._isEs();
            var last = history[history.length - 1];
            var r = last.results || {};
            var totalRevenue = r.revenue || 0;
            var newTechPct = r.newTechPct || 0;
            var coreMarket = r.coreMarketShare || 0;
            var lionCap = r.lionCap || 0;

            var score = 0;
            score += Math.min(300, (totalRevenue / 220) * 300);
            score += Math.min(250, (coreMarket / 65) * 250);
            score += Math.min(250, (newTechPct / 25) * 250);
            var rdEff = totalRevenue > 0 ? totalRevenue / (182 * 0.046 * 4) : 1;
            score += Math.min(200, (rdEff / 1.8) * 200);
            score = Math.round(score);

            var performance = isEs ? 'Disrumpido' : 'Disrupted';
            if (score > 350) performance = isEs ? 'Sobreviviente' : 'Survivor';
            if (score > 550) performance = isEs ? 'Adaptador' : 'Adapter';
            if (score > 750) performance = isEs ? 'Innovador' : 'Innovator';
            if (score > 900) performance = isEs ? 'Líder Ambidiestro' : 'Ambidextrous Leader';

            var insights = [];
            if (newTechPct >= 25) {
                insights.push(isEs ? 'Portafolio sólido de tecnología disruptiva — logró construir nuevas fuentes de ingresos.' : 'Strong disruptive technology portfolio — successfully built new revenue streams.');
            } else if (newTechPct >= 10) {
                insights.push(isEs ? 'Diversificación tecnológica moderada — considere acelerar la adopción de nuevas tecnologías.' : 'Moderate technology diversification — consider accelerating new technology adoption.');
            } else {
                insights.push(isEs ? 'Bajos ingresos de tecnología nueva — el negocio central domina pero es vulnerable a mayor disrupción.' : 'Low new technology revenue — the core business dominates but is vulnerable to further disruption.');
            }
            if (coreMarket >= 65) {
                insights.push(isEs ? 'Mercado central retenido eficazmente — buen equilibrio entre inversión sostenida y disruptiva.' : 'Core market retained effectively — good balance of sustaining and disruptive investment.');
            } else {
                insights.push(isEs ? 'Se perdió una parte significativa del mercado central ante entrantes disruptivos — el dilema del innovador se materializó.' : 'Significant core market share lost to disruptive entrants — the innovation dilemma played out.');
            }
            if (lionCap >= 60) {
                insights.push(isEs ? 'La capacidad Li-Ion es competitiva — bien posicionado para el futuro eléctrico.' : 'Li-Ion capability is competitive — well-positioned for the electric future.');
            } else {
                insights.push(isEs ? 'La brecha en capacidad Li-Ion es un riesgo estratégico. Considere el valor de opción real de continuar invirtiendo.' : 'Li-Ion capability gap is a strategic risk. Consider the real options value of continued investment.');
            }

            return {
                score: score,
                totalRevenue: totalRevenue,
                newTechPct: newTechPct,
                coreMarketShare: coreMarket,
                performance: performance,
                insights: insights
            };
        }

